entries[221453] = { ["name"] = "Band des kochenden Blutes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Magier\nBenötigt Stufe 50\nAnlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 17." }
entries[221454] = { ["name"] = "Gletscherblutband", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Magier\nBenötigt Stufe 50\nAnlegen: Erhöht durch Frostzauber und Frosteffekte zugefügten Schaden um bis zu 17." }
entries[221455] = { ["name"] = "Blutlichtverehrung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchmuck\n+8 Ausdauer\nKlassen: Paladin\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 29.\nAnlegen: Stellt alle 5 Sek. 7 Punkt(e) Mana wieder her." }
entries[221456] = { ["name"] = "Verfinsterter Blutsäbel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nWaffenhand Schwert\n35 - 71 Schaden Tempo 1.50\n(35.33 Schaden pro Sekunde)\n+14 Ausdauer\n+6 Intelligenz\nHaltbarkeit 105 / 105\nKlassen: Paladin\nBenötigt Stufe 50\nAnlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 24." }
entries[221457] = { ["name"] = "Buchband der drakonischen Zerstörung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nRelikt\nKlassen: Paladin\nBenötigt Stufe 50\nAnlegen: Angriffskraft im Kampf gegen Drachkin um 36 erhöht." }
entries[221458] = { ["name"] = "Schattenband des Sieges", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Priester\nBenötigt Stufe 50\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 17." }
entries[221459] = { ["name"] = "Siegel der Geopferten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+6 Intelligenz\nKlassen: Priester\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 20." }
entries[221460] = { ["name"] = "Meuchler der Gurubashi", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nEinhändig Dolch\n51 - 94 Schaden Tempo 1.80\n(40.28 Schaden pro Sekunde)\n+7 Ausdauer\nHaltbarkeit 75 / 75\nKlassen: Schurke\nBenötigt Stufe 50\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%." }
entries[221461] = { ["name"] = "Rune des Massakers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Armschienen mit der Rune 'Massaker':\n\nEure Fähigkeiten fügen Zielen, die von einem Eurer Blutungseffekte betroffen sind, 15% mehr Schaden zu. 'Blutung' heilt Euch zudem um 40% des von ihr verursachten Schadens.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221462] = { ["name"] = "Blutiges Schwert der Geschwindigkeit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nEinhändig Schwert\n48 - 89 Schaden Tempo 1.70\n(40.29 Schaden pro Sekunde)\n+8 Beweglichkeit\n+8 Ausdauer\nHaltbarkeit 105 / 105\nKlassen: Schurke\nBenötigt Stufe 50\nTrefferchance: Erhöht die Laufgeschwindigkeit 10 Sek. lang um 40%." }
entries[221463] = { ["name"] = "Voodoopuppe der Ahnen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchmuck\n+8 Ausdauer\nKlassen: Schamane\nBenötigt Stufe 50\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 29.\nAnlegen: Stellt alle 5 Sek. 7 Punkt(e) Mana wieder her." }
entries[221464] = { ["name"] = "Totem der feurigen Präzision", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nRelikt\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 50\nAnlegen: Erhöht die Reichweite Eures Zaubers 'Flammenschock' um 5 Meter." }
entries[221465] = { ["name"] = "Verderbter Schadensbringer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nZweihändig Streitkolben\n150 - 226 Schaden Tempo 3.60\n(52.22 Schaden pro Sekunde)\n+15 Stärke\n+28 Ausdauer\n+6 Intelligenz\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 50\nTrefferchance: Setzt das Ziel 2 Sek. lang außer Gefecht." }
entries[221466] = { ["name"] = "Schleife des brennenden Bluts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Hexenmeister\nBenötigt Stufe 50\nAnlegen: Erhöht durch Feuerzauber und Feuereffekte zugefügten Schaden um bis zu 17." }
entries[221467] = { ["name"] = "Auge des Blutmonds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nFinger\n+14 Ausdauer\n+4 Intelligenz\nKlassen: Hexenmeister\nBenötigt Stufe 50\nAnlegen: Erhöht durch Schattenzauber und Schatteneffekte zugefügten Schaden um bis zu 17." }
entries[221468] = { ["name"] = "Mauer des Flüsterns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nSchildhand} Schild\n1902 Rüstung\n34 Blocken\n+6 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Krieger\nBenötigt Stufe 50\nAnlegen: Bei einem Treffer durch einen gegnerischen Zauber besteht eine Chance von 5%, dass der Angreifer 3 Sek. lang zum Schweigen gebracht wird. (Procchance: 5%, 20s Abklingzeit)" }
entries[221469] = { ["name"] = "Stachelspeer des Kopfjägers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: [Blood Moon] (1)\nWurfwaffe Wurfwaffe\n70 - 130 Schaden Tempo 3.00\n(33.33 Schaden pro Sekunde)\nKlassen: Krieger\nBenötigt Stufe 50\nBenutzen: Schleudert den Speer auf das Ziel und macht es bis zu 5 Sek. lang bewegungsunfähig. (5 Min Abklingzeit)" }
entries[221470] = { ["name"] = "Traumsmaragd" }
entries[221471] = { ["name"] = "Truhe des Smaragdwärters", ["text"] = "Wird beim Aufheben gebunden\n<Zum Öffnen rechtsklicken>" }
entries[221473] = { ["name"] = "Rune des Wachmanns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Helm mit der Rune 'Wachsamkeit':\n\nFokussiert Euren schützenden Blick auf ein Gruppen- oder Schlachtzugsmitglied, verringert so seinen erlittenen Schaden um 3% und überträgt 10% seiner erzeugten Bedrohung auf Euch. Zusätzlich wird jedes Mal, wenn das Ziel von einem Angriff getroffen wird, die Abklingzeit Eurer Fähigkeit 'Spott' abgeschlossen. Hält 30 Min. lang an. Dieser Effekt kann nur auf jeweils einem Ziel wirken.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221474] = { ["name"] = "Gebundene Essenz des Eranikus", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\n+10 Ausdauer\n+10 Naturwiderstand\nBenötigt Stufe 50\nBenutzen: Vergiftet alle Gegner im Umkreis von 8 Metern um den Zaubernden. Die Opfer des Giftes erleiden 45 Sek. lang alle 5 Sek. 50 Naturschaden. (10 Min Abklingzeit)" }
entries[221475] = { ["name"] = "Essenz des Eranikus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nBenötigt Stufe 50\n\"Grüne Nebel wirbeln in den Facetten dieses Edelsteins.\"" }
entries[221480] = { ["name"] = "Zaubernotizen: Geschmolzene Rüstung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Armschienen mit der Rune 'Glühende Rüstung':\n\nFügt einem Gegner [Quellwert] Feuerschaden zu, wenn Ihr getroffen werdet. Erhöht Eure kritische Zaubertrefferchance um 5% und verringert die Chance, dass Ihr kritische Treffer erleidet, um 5%. Es kann immer nur ein Rüstungszauber zur selben Zeit auf dem Magier aktiv sein. Hält 30 Min. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[221481] = { ["name"] = "Nihilistische Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Armschienen mit der Rune 'Zone der Leere':\n\nBeschwört eine 'Zone der Leere' im Zielbereich, die allen Gegnern, die sich darin befinden, 10 Sek. lang pro Sekunde [Quellwert] Schattenschaden zufügt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[221482] = { ["name"] = "Rune des Gebrechens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Armschienen mit der Rune 'Instabiles Gebrechen':\n\nSchattenenergie zerstört langsam das Ziel und verursacht im Verlauf von 18 Sek. insgesamt [Quellwert] Schaden. Sollte 'Instabiles Gebrechen' gebannt werden, erleidet der Bannende [Quellwert] Schaden und wird 5 Sek. lang zum Schweigen gebracht. Es kann pro Hexenmeister jeweils nur ein Effekt von 'Instabiles Gebrechen' oder 'Feuerbrand' gleichzeitig auf einem beliebigen Ziel aktiv sein.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[221483] = { ["name"] = "Rune des Brands", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Helm mit der Rune 'Brennen':\n\nEuer 'Flammenschock' trifft jetzt bis zu 5 Ziele, hat eine 6 Sek. längere Effektdauer und verursacht 100% mehr Schaden. Zusätzlich wird Euer Zauberschaden um 150% Eurer Intelligenz erhöht, während Eure ausgerüstete Waffenhandwaffe mit 'Waffe der Flammenzunge' verzaubert ist.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221484] = { ["name"] = "Hexerstecken des Hexendoktors", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenutzen: Verhext Euch selbst, um im Versunkenen Tempel etwas schwerer entdeckt zu werden. (3 Sek. Abklingzeit)" }
entries[221487] = { ["name"] = "Zaubernotizen: Fortgeschrittener Schutzzauber", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Helm mit der Rune 'Fortgeschrittener Schutzzauber':\n\nEure Zauber 'Manaschild', 'Frostzauberschutz' und 'Feuerzauberschutz' können jetzt auf verbündete Ziele gewirkt werden und absorbieren 100% mehr Schaden. 'Manaschild' verbraucht 50% weniger Mana pro absorbiertem Schaden. Außerdem wird 'Geringen Fluch aufheben' durch 'Großen Fluch aufheben' ersetzt.\n\nEntfernt 1 Fluch und 1 schädlichen Magieeffekt von einem verbündeten Ziel.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221488] = { ["name"] = "Resolute Offenbarung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Helm mit der Rune 'Göttliche Aegis':\n\nKritische Heilungen hüllen das Ziel in einen schützenden Schild, der Schaden in Höhe von 30% des geheilten Wertes absorbiert. Hält 12 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221489] = { ["name"] = "Rune der Rache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Helm mit der Rune 'Rache':\n\nWenn diese Fähigkeit aktiviert wird, gewährt sie Euch 20 Sek. lang vorübergehend um 30% erhöhte maximale Gesundheit. Wenn der Effekt abklingt, geht die zusätzliche Gesundheit wieder verloren. Außerdem sorgt 'Rache' dafür, dass Eure Flügel, während 'Metamorphose' aktiv ist, Eure Fallgeschwindigkeit verringern.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221490] = { ["name"] = "Rune der Springflut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Eure Armschienen mit der Rune 'Springflut':\n\nHeilt ein verbündetes Ziel um [Quellwert] bis [Quellwert] Gesundheit und im Verlauf von 15 Sek. um weitere [Quellwert] Gesundheit. Wenn Ihr innerhalb von 15 Sek. 'Kettenheilung' auf dieses Hauptziel wirkt, wird die hervorgerufene Heilung um 25% erhöht. Dieser Zauber löst außerdem 'Erwachen der Ahnen' aus.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[221491] = { ["name"] = "Schattenzahntasche", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält eine zufällige Dunkelmond-Karte.\"\n<Zum Öffnen rechtsklicken>" }
entries[221497] = { ["name"] = "Alter Schlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nBenutzen: Öffnet eine alte Truhe." }
entries[221498] = { ["name"] = "Stabile Vesperdose", ["text"] = "Wird beim Aufheben gebunden\n12 Platz Behälter" }
entries[221499] = { ["name"] = "Rune der Teufelswache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Armschienen mit der Rune 'Teufelswache beschwören':\n\nBeschwört eine Teufelswache, die unter dem Befehl des Hexenmeisters steht.\n\nDie Teufelswache profitiert von allen Talenten und Effekten, die von anderen Dämonendienern ausgelöst werden oder die daraus einen Vorteil ziehen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221510] = { ["name"] = "Rune des Ritters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Eure Armschienen mit der Rune 'Schwert und Schild':\n\nWenn Eure Fähigkeiten 'Verwüsten' und 'Rache' Schaden verursachen, besteht eine Chance von 30%, die Abklingzeit von 'Schildschlag' abzuschließen und die Wutkosten der Fähigkeit 5 Sek. lang um 100% zu verringern.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221511] = { ["name"] = "Rune des Beschützers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Helm mit der Rune 'Schildmeisterschaft':\n\nErhöht den gesamten von Euch verursachten körperlichen Schaden um 10%, während Ihr ein Schild ausgerüstet habt, und verringert die Dauer aller auf Euch angewandten Entwaffnungseffekte um 50%. Dieser Effekt ist mit anderen Effekten, welche die Entwaffnungsdauer verringern, nicht stapelbar.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221512] = { ["name"] = "Rune des Eifers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Eure Armschienen mit der Rune 'In Stücke schneiden':\n\nEure Fähigkeiten 'Ausweiden' und 'Vergiften' erneuern die Dauer Eurer Fähigkeit 'Zerhäckseln' oder 'Klingentanz' auf ihre maximalen Combopunkte von 5. Wenn beide aktiv sind, wird nur die geringste verbleibende Dauer erneuert.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221513] = { ["name"] = "Rune der Kraft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nPrägt Euren Helm mit der Rune 'Kampfkraft':\n\nIhr habt eine Chance von 20%, jedes Mal 15 Energie zu erhalten, wenn Ihr Nahkampfschaden mit Eurer Schildhandwaffe verursacht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221514] = { ["name"] = "Rune der Feuerkraft", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nPrägt Euren Helm mit der Rune 'Sichern und Laden':\n\nJedes Mal, wenn Ihr eine Falle platziert, kostet Eure nächste Schussfähigkeit (mit Ausnahme von 'Streuschuss') innerhalb von 20 Sek. kein Mana und löst keine Abklingzeit aus.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221515] = { ["name"] = "Rune der Detonation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Eure Armschienen mit der Rune 'T.N.T.':\n\nErhöht von 'Explosivschuss' und all Euren Schadensfallen verursachten Schaden um 10%. Zudem werden der anfängliche Schaden von 'Sprengfalle' sowie der gesamte regelmäßige Schaden Eurer 'Feuerbrandfalle' um 25% Eurer Nahkampf- oder Distanzangriffskraft erhöht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221516] = { ["name"] = "Rune der urtümlichen Energie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Eure Armschienen mit der Rune 'Verbesserte rasende Regeneration':\n\nEure 'Rasende Regeneration' kann jetzt in allen Gestalten mit Ausnahme der Moonkingestalt oder im unverwandelten Zustand genutzt werden. Sie konvertiert nun Eure aktive Ressource 10 Sek. lang sekündlich in Gesundheit. Bis zu 10 Wut, 10 Energie oder 20% Grundmana werden pro Sekunde in bis zu 10% Gesundheit konvertiert.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221517] = { ["name"] = "Rune des Blutvergießens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Druide\nPrägt Euren Helm mit der Rune 'Aufspießen':\n\nWenn Ihr ein Ziel mit 'Aufschlitzen', 'Prankenhieb' oder 'Zermalmen' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Zerfleischen (Bär)' abgeschlossen und 10 Wut erzeugt wird. Wenn Ihr ein Ziel mit 'Zerfleischen' (Katze) oder 'Schreddern' trefft, besteht eine Chance von 15%, dass die Abklingzeit von 'Tigerfuror' abgeschlossen wird.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[221518] = { ["name"] = "Flüstern", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n109 - 163 Schaden Tempo 2.60\n(52.31 Schaden pro Sekunde)\n+20 Stärke\n+12 Ausdauer\nHaltbarkeit 100 / 100\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%." }
entries[221519] = { ["name"] = "Kugel der Mannoroc", ["text"] = "Questgegenstand\nEinzigartig" }
entries[221544] = { ["name"] = "Sturmkrähenei", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[221545] = { ["name"] = "Entschlüsselte Hexenmeisternotizen", ["text"] = "Einzigartig\nKlassen: Priester , Schamane" }
entries[221547] = { ["name"] = "Verschlüsselte Hexenmeisternotizen", ["text"] = "Einzigartig\nBenutzen: Um die Notizen des Hexenmeisters zu verstehen, ist eine Glyphe erforderlich. Wer weiß, welche Magie sie enthält?" }
entries[221549] = { ["name"] = "Chiffre der Wüstenläufer", ["text"] = "\"Hilft bei der Übersetzung der von den Banditen der Wüstenläufer geschriebenen Dokumente.\"" }
entries[221780] = { ["name"] = "Prinzessin Theradras' Szepter", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Streitkolben\n111 - 174 Schaden Tempo 3.40\n(41.91 Schaden pro Sekunde)\n90 Rüstung\n+13 Stärke\n+10 Beweglichkeit\n+15 Ausdauer\n+9 Willenskraft\nHaltbarkeit 100 / 100\nBenötigt Stufe 46\nAnlegen: +67 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt." }
entries[221781] = { ["name"] = "Avenwachthelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n469 Rüstung\n+10 Stärke\n+5 Beweglichkeit\n+25 Ausdauer\nHaltbarkeit 80 / 80" }
entries[221782] = { ["name"] = "Helm des Banns", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n266 Rüstung\n+11 Beweglichkeit\n+18 Intelligenz\nHaltbarkeit 70 / 70\nAnlegen: +36 Angriffskraft." }
entries[221783] = { ["name"] = "Schiftung der Gerechtigkeit", ["text"] = "Wird beim Aufheben gebunden\nSchulter Platte\n562 Rüstung\n+17 Stärke\n+15 Ausdauer\n+7 Feuerwiderstand\nHaltbarkeit 100 / 100\nKlassen: Paladin\nBenötigt Stufe 60\nAnlegen: Erhöht durch Heiligzauber und Heiligeffekte zugefügten Schaden um bis zu 21.\nAnlegen: Erhöht Eure Trefferchance mit allen Angriffen und Zaubern um 1%.\n\nStrahlen der Gerechtigkeit (0/8)\nKampfstiefel der Gerechtigkeit\nBrustplatte der Gerechtigkeit\nKrone der Gerechtigkeit\nGurt der Gerechtigkeit\nHandschutz der Gerechtigkeit\nGamaschen der Gerechtigkeit\nSchiftung der Gerechtigkeit\nKriegsbänder der Gerechtigkeit\n(2) Set : 'Richturteil des Lichts' und 'Richturteil der Weisheit' gewähren zusätzlich die Effekte von 'Richturteil des Kreuzfahrers'.\n(4) Set : Erhöht die kritische Trefferchance Eurer Zauber und Angriffe um 2%.\n(6) Set : Eure Fähigkeiten 'Siegel des Befehls', 'Siegel der Rechtschaffenheit', 'Siegel des Märtyrertums' und 'Sonnenlicht' verursachen 35% weniger Schaden, halten jetzt allerdings nach Einsatz eines weiteren Siegels noch 6 Sek. an, oder bis Ihr ein drittes Siegel einsetzt. 'Richturteil' kann mehrere Siegel auslösen, wenn sie aktiv sind." }
entries[221785] = { ["name"] = "Gewand des Cenarius", ["text"] = "Wird beim Aufheben gebunden\nBrust Leder\n200 Rüstung\n+11 Ausdauer\n+17 Intelligenz\n+15 Willenskraft\n+10 Feuerwiderstand\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 60\nAnlegen: Erhöht durch Zauber und Effekte verursachte Heilung um bis zu 62.\n\nFülle des Cenarius (0/8)\nGürtel des Cenarius\nStiefel des Cenarius\nArmschienen des Cenarius\nHandschuhe des Cenarius\nHelm des Cenarius\nGamaschen des Cenarius\nSchiftung des Cenarius\nGewand des Cenarius\n(2) Set : Wenn Ihr 'Anregen' auf einen anderen Spielercharakter wirkt, ist auch Euer Charakter betroffen.\n(4) Set : Wenn Ihr Eure Zauber 'Heilende Berührung' oder 'Pflege' wirkt, erhaltet Ihr mit einer Chance von 25% Mana in Höhe von 35% der Grundkosten des Zaubers. (Procchance: 25%, 1s Abklingzeit)\n(6) Set : Verringert die Abklingzeit von 'Gelassenheit' um 100% und erhöht ihre Heilung um 100%. (Procchance: 25%, 1s Abklingzeit)" }
entries[221971] = { ["name"] = "Traumschwurhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Kombiniert alle gesammelten Reagenzien zu einer Rune, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Ein einzigartiges Reagenz, das eine feurige Essenz in sich trägt. Ihr könnt eine neue Rune schnitzen, wenn Ihr ähnliche Komponenten findet.\"" }
entries[221972] = { ["name"] = "Traumloderfeuer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Kombiniert alle gesammelten Reagenzien zu einer Rune, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Ein einzigartiges Reagenz, das eine feurige Essenz in sich trägt. Ihr könnt eine neue Rune schnitzen, wenn Ihr ähnliche Komponenten findet.\"" }
entries[221973] = { ["name"] = "Traumjägerreißzahn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Kombiniert alle gesammelten Reagenzien zu einer Rune, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Ein einzigartiges Reagenz, das eine feurige Essenz in sich trägt. Ihr könnt eine neue Rune schnitzen, wenn Ihr ähnliche Komponenten findet.\"" }
entries[221974] = { ["name"] = "Halskette der Grimmtotem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Fügt die gesammelten Reagenzien zu einem zerbrechlichen Stab zusammen, der den unvergänglichen Schlummer beenden kann.\n\"Eine Halskette, die von einem erkrankten Schamanen der Grimmtotem gesammelt wurde.\"" }
entries[221975] = { ["name"] = "Zerbrochener Stab der Waldpfoten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Fügt die gesammelten Reagenzien zu einem zerbrechlichen Stab zusammen, der den unvergänglichen Schlummer beenden kann.\n\"Teil eines Stabs, der von einem erkrankten Mystiker der Waldpfoten gesammelt wurde.\"" }
entries[221976] = { ["name"] = "Verseuchter Naturstab", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nBenutzen: Erweckt das aktuelle Ziel aus unvergänglichem Schlummer.\n\"Der Stab hält kaum zusammen, aber die uralte Magie im Inneren könnte trotzdem noch zu gebrauchen sein.\"" }
entries[221978] = { ["name"] = "Seele des Forschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBeschwört einen Wichtelforscher. Er kann zwar nicht kämpfen, dafür reist er aber durch Portale, um andere Welten zu erforschen und Schätze mitzubringen.\n\"Erlernt, wie man einen Wichtelforscher beschwört.\"" }
entries[221979] = { ["name"] = "Prophezeiung des tiefgrünen Winters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Helm mit der Rune 'Schmerz und Leid':\n\n'Gedankenschlag', 'Gedankenstachel' und 'Gedankenschinden' setzen die Dauer von 'Schattenwort: Schmerz', 'Pest der Leere' oder 'Vampirberührung' auf Eurem Ziel auf das Maximum zurück. Es wird immer die Fähigkeit mit der geringsten verbleibenden Dauer aufgefrischt.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[221980] = { ["name"] = "Prophezeiung des erwachten Chaos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Euren Helm mit der Rune 'Auge der Leere':\n\nRuft ein Auge der Leere, das 30 Sek. lang für Euch kämpft. Das Auge kann verschiedene Flüche auf Euer Ziel wirken.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[221981] = { ["name"] = "Prophezeiung des verlorenen Stammes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Priester\nPrägt Eure Armschienen mit der Rune 'Woge des Lichts':\n\nKritische Zaubertreffer sorgen dafür, dass Ihr 'Heilige Pein' oder 'Blitzheilung' beim nächsten Mal innerhalb von 15 Sek. sofort wirkt.\nBenutzen: Konzentriert Euch auf die Prophezeiung, um einen neuen Zauber zu lernen. Erfordert einen durch Meditation über zwei spirituelle Geheimnisse Azeroths konzentrierten Geist." }
entries[222952] = { ["name"] = "Fläschchen der ruhelosen Träume", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Stufe 50\nBenötigt Alchimie (250)\nBenutzen: Erhöht 1 Stunde lang den durch Zauber verursachten Schaden um 30, die verursachte Heilung um bis zu 45 Gesundheit und die Manaregeneration um 12 Mana pro 5 Sek. Die Vorteile dieses Fläschchens wirken nur in Gebieten, die unter dem Einfluss des Alptraums stehen. (30 Sek. Abklingzeit)\n\"Die Flasche scheint nie leer zu werden, egal, wie viel man davon trinkt.\"" }
entries[222962] = { ["name"] = "Weisheit des Hyjal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erlernt eine neue Runenschnitzenfähigkeit." }
