entries[223074] = { ["name"] = "Panzerbeinplatten des Leutnants", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n277 Rüstung\n+12 Stärke\n+13 Ausdauer\n+12 Intelligenz\nHaltbarkeit 90 / 90\nKlassen: Jäger , Schamane\nBenötigt Stufe 50\nAnlegen: Erhöht Eure kritische Trefferchance aller Eurer Angriffe und Zauber um 1%.\n\nPanzerrüstung des Hauptmanns (0/6)\nPanzerrüstung des Leutnants\nPanzersabatons des Fähnrichs\nPanzerstulpen des Fähnrichs\nPanzerhelm des Hauptmanns\nPanzerbeinplatten des Leutnants\nPanzerschulterklappen des Hauptmanns\n(3) Set : +15 Ausdauer.\n(6) Set : +30 Angriffskraft." }
