entries[223147] = { ["name"] = "Zaubernotizen: Qualfeuerblitz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Eure Armschienen mit der Rune 'Qualfeuerblitz':\n\nEntfesselt eine realitätsverzerrende Explosion aus roher Magie auf Euren Gegner, die ihm zwischen [Quellwert] und [Quellwert] Schimärenschaden zufügt.\n\nErhöht [Quellwert] lang den Schaden Eurer Fähigkeiten 'Qualfeuerblitz' und 'Pyroschlag' um 25% und verringert Eure Willenskraft um 20%. Bis zu 5-mal stapelbar. Fällt Eure Willenskraft auf 0, sterbt Ihr.\n\nDer Schaden dieses Zaubers wird gegen den geringsten Wert vom Arkan-, Feuer- und Frostwiderstand des Ziels gerechnet.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
