entries[224279] = { ["name"] = "Terrestris", ["text"] = "Wird beim Aufheben gebunden\nSchildhand} Schild\n2964 Rüstung\n55 Blocken\n+17 Ausdauer\nHaltbarkeit 120 / 120\nKlassen: Schamane\nBenötigt Stufe 60\nAnlegen: Verteidigung +7.\nAnlegen: Beschworene Totems gewähren einen Segen ihres Elements.\nBenutzen: Entfacht die Flammen von Terrestris und heizt ihn für die Offensive an. (1 Min Abklingzeit)" }
entries[224280] = { ["name"] = "Suzerain, Verteidiger der Drachenschwärme", ["text"] = "Wird beim Aufheben gebunden\nSchildhand} Schild\n2964 Rüstung\n55 Blocken\n+15 Stärke\nHaltbarkeit 120 / 120\nKlassen: Krieger\nBenötigt Stufe 60\nAnlegen: Schützt den Träger davor, vollständig von der Schattenflamme verzehrt zu werden.\nAnlegen: Verteidigung +10.\nAnlegen: Erhöht den Blockwert Eures Schildes um 18.\nBenutzen: Hebt Suzerain 5 Sek. lang empor, wodurch Ihr 50% weniger Zauberschaden erleidet. Wenn Ihr von 'Drachenodem' getroffen werdet, erhaltet Ihr 'Suzerains Zorn', was Euch 10 Sek. lang 30% Bonusschaden gegen Drachen verleiht. (1 Min Abklingzeit)" }
entries[224281] = { ["name"] = "Gla'sir", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n140 - 241 Schaden Tempo 3.20\n(59.53 Schaden pro Sekunde)\n+12 Ausdauer\n+26 Intelligenz\n+14 Willenskraft\n+10 Naturwiderstand\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 60\nAnlegen: Erhöht Eure kritische Trefferchance mit allen Angriffen und Zaubern um 2%.\nAnlegen: Erhöht durch sämtliche Zauber und magische Effekte verursachte Heilung um bis zu 144 und den verursachten Schaden um bis zu 77.\nAnlegen: Kritische Effekte von Heilungen haben eine Chance, 3 Verbündete in der Nähe um 200 bis 350 Gesundheit zu heilen, und kritische Treffer mit Zaubern haben eine Chance, 3 Gegnern in der Nähe 100 bis 175 Naturschaden zuzufügen. (Procchance: 15%, 15s Abklingzeit)\nBenutzen: Verwandelt Gla'sir in Rae'lar. (1 Min Abklingzeit)" }
entries[224282] = { ["name"] = "Rae'lar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nZweihändig Stab\n125 - 226 Schaden Tempo 3.20\n(54.84 Schaden pro Sekunde)\n+26 Stärke\n+23 Beweglichkeit\n+12 Ausdauer\n+10 Naturwiderstand\nHaltbarkeit 120 / 120\nKlassen: Druide\nBenötigt Stufe 60\nAnlegen: +338 Angriffskraft in Katzengestalt, Bärengestalt oder Terrorbärengestalt.\nAnlegen: Chance bei automatischen Nahkampfangriffen, dem anvisierten Gegner bei einem Treffer 140 bis 220 Leben zu rauben.\nBenutzen: Verwandelt Rae'lar in Gla'sir. (1 Min Abklingzeit)" }
entries[224409] = { ["name"] = "Schlangenschläger", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Faustwaffe\n73 - 136 Schaden Tempo 2.60\n(40.19 Schaden pro Sekunde)\n+9 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 75 / 75\nBenötigt Stufe 50\nTrefferchance: Vergiftet den Gegner und verursacht 50 Naturschaden, verringert den Naturwiderstand um 60 und erhöht sämtlichen erlittenen Heilig- und Naturschaden 20 Sek. lang um 8%. Wirkt nur bei Gegnern der Stufe 55 oder niedriger.\n\nAufstieg der Schlange (0/2)\nKobragiftzahnklaue\nSchlangenschläger\n(2) Set : Gewährt dem Benutzer beim Verursachen von Distanz- oder Nahkampfschaden eine kleine Chance, mit dem Segen der Schlange erfüllt zu werden. Distanz- und Nahkampfangriffskraft 12 Sek. lang um 150 erhöht. (Procchance: 3%, 2Min. Abklingzeit)" }
entries[224806] = { ["name"] = "Portalempfänger der Legion", ["text"] = "Benutzen: Verbindet eine Teufelsnarbe oder einen Teufelsriss mit einer Welt tief im Raum der Legion. Das kann unvorhersehbare und gefährliche Auswirkungen haben.\n5 Aufladungen" }
