entries[224893] = { ["name"] = "Überladener Portalempfänger", ["text"] = "Benutzen: Verbindet eine Teufelsnarbe oder einen Teufelsriss mit einer Welt tief im Raum der Legion. Das kann unvorhersehbare und gefährliche Auswirkungen haben.\n2 Aufladungen" }
entries[224912] = { ["name"] = "Portalempfängerempfänger", ["text"] = "Benutzen: Überladet einen Portalempfänger der Legion." }
entries[225675] = { ["name"] = "Rußbedeckter Obsidiankern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Poliert den Ruß ab." }
entries[225676] = { ["name"] = "Geschmolzener Obsidiankern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 10 min (Realzeit)\n\"Kühlt ihn ab, bevor er schmilzt!\"" }
entries[225686] = { ["name"] = "Rune der Dezimierung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Eure Stiefel mit der Rune 'Dezimierung':\n\nEuer Zauber 'Seelenfeuer' hat keine Abklingzeit mehr. Wenn Ihr Eure Zauber 'Schattenblitz', 'Schattenspalten', 'Verbrennen' oder 'Seelenfeuer' auf ein Ziel wirkt, das 35% Gesundheit oder weniger besitzt, wird die Zauberzeit von 'Seelenfeuer' 10 Sek. lang um 40% verringert. Wenn Ihr 'Seelenfeuer' einsetzt, während Ihr unter dem Effekt von 'Dezimierung' steht, kostet der Zauber keinen Seelensplitter.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[225687] = { ["name"] = "Rune der höllischen Rüstung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Umhang mit der Rune 'Höllische Rüstung':\n\nEuer Geist wird von dämonischer Energie erfüllt, was Euren sämtlichen erlittenen magischen Schaden um einen Prozentsatz verringert, der 60% Eurer körperlichen Schadensverringerung durch Rüstung entspricht. Hält 10 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[225688] = { ["name"] = "Rune des Mals des Chaos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Hexenmeister\nPrägt Euren Umhang mit der Rune 'Mal des Chaos':\n\nMit Ausnahme von 'Fluch der Schatten' und 'Fluch der Elemente' belegen all Eure Flüche das Ziel nun mit 'Mal des Chaos', wodurch dessen Arkan-, Feuer-, Frost-, Natur- und Schattenwiderstand um [Max(Min( 56 + 19, 75), 27)] verringert und sämtlicher erlittener Zauberschaden dieser Magiearten um [Max(Min(( 56 - 8) * 0.125 + 4, 10), 4)]% erhöht wird, solange der Fluch andauert.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[225689] = { ["name"] = "Zaubernotizen: Arkanbeschuss", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Umhang mit der Rune 'Arkanbeschuss':\n\nSchleudert mehrere Geschosse auf das gegnerische Ziel und verursacht [Quellwert] bis [Quellwert] Arkanschaden. Dieser Zauber hat außerdem eine Chance von 25%, 'Geschosssalve' auszulösen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[225690] = { ["name"] = "Zaubernotizen: Gefrorene Kugel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Umhang mit der Rune\n'Gefrorene Kugel':\n\nSchleudert eine Kugel aus wirbelndem Eis, die sich im Verlauf von 16 Sek. schnell nach vorne bewegt. Während sie sich bewegt, verursacht die Kugel alle 1 Sek. [Quellwert] Frostschaden und belegt alle Gegner, durch die sie sich bewegt, mit 'Kühlung' und verringert ihre Bewegungsgeschwindigkeit um 30%. Sobald sie einem Gegner zum ersten Mal Schaden zufügt, verlangsamt sie ihre Bewegung und hat eine Chance von 100%, die Rune 'Eisige Finger' auszulösen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"", ["unresolvedValues"] = true }
entries[225691] = { ["name"] = "Zaubernotizen: Überhitzen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nPrägt Euren Umhang mit der Rune 'Überhitzen':\n\n'Feuerschlag' trifft immer kritisch, kann gewirkt werden, während Ihr einen anderen Zauber wirkt, und ist nicht von der globalen Abklingzeit betroffen. Die Abklingzeit ist jedoch um 15 Sek. erhöht.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[225740] = { ["name"] = "Rune der Beherrschung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Umhang mit der Rune 'Kohärenz':\n\nDie Effektivität Eurer 'Kettenheilung' wird nur um 35% pro Übersprung verringert und die Effektivität von 'Kettenblitzschlag' nur um 20% Prozent pro Übersprung. Springt außerdem auf 1 zusätzliches Ziel über.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[225838] = { ["name"] = "Voltaische Ikone", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt Totem\nKlassen: Schamane\nPrägt Euren Umhang mit der Rune 'Sturm, Erde und Feuer':\n\nVerringert die Abklingzeit Eures Zaubers 'Kettenblitzschlag' um 25%, verleiht Eurem Totem der Erdbindung eine Chance, Ziele 5 Sek. lang festzuwurzeln, wenn es aufgestellt wird, und erhöht den regelmäßigen Schaden Eures Zaubers 'Flammenschock' um 60%.\n\"Erlernt eine neue Fähigkeit, nachdem Ihr 3 Gegner mit einem einzelnen Einsatz von 'Kettenblitzschlag' besiegt.\"" }
entries[225893] = { ["name"] = "Epochenende", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig: (Unbekannt #636) (0)\nZweihändig Schwert\n300 - 415 Schaden Tempo 4.20\n(85.12 Schaden pro Sekunde)\n-322 Ausdauer\nHaltbarkeit 120 / 120\nBenötigt Stufe 77" }
entries[225914] = { ["name"] = "Rune des gebundenen Geistes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nPrägt Euren Umhang mit der Rune 'Wildgeist':\n\nBeschwört zwei Geisterwölfe, die unter dem Befehl des Schamanen stehen. Hält 45 Sek. lang an.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[225929] = { ["name"] = "Verseuchter Seelensplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (3)" }
entries[225938] = { ["name"] = "Zerrissene Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\"" }
entries[225939] = { ["name"] = "Zerrissene Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\"" }
entries[225940] = { ["name"] = "Zerrissene Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\"" }
entries[225941] = { ["name"] = "Zerrissene Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Magier\nBenutzen: Kombiniert alle gesammelten zerrissenen Zaubernotizen zu einer Schriftrolle, die Euch einen neuen Runenschnitzenzauber lehrt.\n\"Eine lückenhafte Seite, die den Schriftrollen zu ähneln scheint, die Runenschnitzenfähigkeiten lehren. Drei Viertel fehlen.\"" }
entries[225942] = { ["name"] = "Besudeltes Eberfleisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Mit Sekret beschichtet.\n\"Braucht vermutlich nur etwas Soße.\"" }
entries[225943] = { ["name"] = "Ranziger Fleischbrocken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: ???\n\"Würde selbst den niedersten Aasfresser zum Würgen bringen.\"" }
entries[225954] = { ["name"] = "Verkohlte Zaubernotizen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\n\"Eine verkohlte, zerrissene Seite, die einst arkane Geheimnisse zu Runenschnitzenfähigkeiten barg, doch durch den Brandschaden unbrauchbar gemacht wurde.\"" }
entries[225955] = { ["name"] = "Rune des Einfallsreichen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Euren Umhang mit der Rune 'Improvisation':\n\nVerringert die Manakosten Eurer Fallen um 100% und ihre Abklingzeiten um 40%.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[226122] = { ["name"] = "Daltons Horn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nRelikt\nBenötigt Stufe 50\nBenutzen: Stößt in Daltons Horn, um Euren Knappen zu beschwören. Euer Knappe wird Euch im Kampf beistehen und bei gemeinsamen Abenteuern von Euch lernen. (Procchance: 3%) (15 Sek. Abklingzeit)\n\"Kokosnüsse nicht enthalten.\"" }
entries[226201] = { ["name"] = "Klinge von Knappe Cuthbert", ["text"] = "Questgegenstand\nEinzigartig\n\"Das Schwert ist verbeult und beschädigt, liegt allerdings gut in der Hand.\"" }
