entries[226252] = { ["name"] = "Rune des Guerrillas", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nPrägt Euren Umhang mit der Rune 'Drauf und weg':\n\nNach dem Einsatz von 'Raptorstoß' wird Eure Bewegungsgeschwindigkeit 15 Sek. lang um 30% erhöht.\n\nDie Schaden verursachenden Fähigkeiten Eures Begleiters belegen das Ziel 2 Min. lang mit 'Tollwütige Raserei', wodurch dessen Nahkampfangriffskraft um 91 erhöht und dessen Rüstung um 640 verringert wird. Tollwütige Gegner flüchten nicht und ignorieren Furcht- und Entsetzenseffekte.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[226374] = { ["name"] = "Okkultes Gift I", ["text"] = "Klassen: Schurke\nBenötigt Stufe 54\n{Benutzen: Überzieht eine Waffe mit Gift, das 30 Min. lang wirkt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, ihm so 108 Naturschaden im Verlauf von 12 Sek. zuzufügen und dabei seinen erlittenen Arkan-, Feuer-, Frost-, Natur- und Schattenschaden um 4% zu erhöhen. Bis zu 5-mal auf einem Ziel stapelbar.\n\n'Okkultes Gift' zählt als 'Tödliches Gift' und profitiert von allen Talenten, die durch 'Tödliches Gift' ausgelöst werden oder dieses modifizieren. (Procchance: 30%)}" }
entries[226394] = { ["name"] = "Handbuch für atrophisches Gift", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nÜberzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was dessen Nahkampfangriffskraft 15 Sek. lang um 205 verringert. 105 Aufladungen.\n\"Lehrt Euch 'Atrophisches Gift'.\"" }
entries[226395] = { ["name"] = "Handbuch für betäubendes Gift", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nÜberzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was die Zeit zwischen dessen Nahkampfangriffen 15 Sek. lang um 20% erhöht. 105 Aufladungen.\n\"Lehrt Euch 'Betäubendes Gift'.\"" }
entries[226396] = { ["name"] = "Handbuch für okkultes Gift", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\n{Überzieht eine Waffe mit Gift, das 30 Min. lang wirkt.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, ihm so 108 Naturschaden im Verlauf von 12 Sek. zuzufügen und dabei seinen erlittenen Arkan-, Feuer-, Frost-, Natur- und Schattenschaden um 4% zu erhöhen. Bis zu 5-mal auf einem Ziel stapelbar.\n\n'Okkultes Gift' zählt als 'Tödliches Gift' und profitiert von allen Talenten, die durch 'Tödliches Gift' ausgelöst werden oder dieses modifizieren.}\n\"Lehrt Euch 'Okkultes Gift'.\"" }
entries[226397] = { ["name"] = "Handbuch für zähes Gifts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schurke\nÜberzieht eine Waffe mit Gift, das 30 Min. lang anhaftet.\nBei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften, was dessen Rüstung 15 Sek. lang um 1700 verringert. 105 Aufladungen.\n\n'Zähes Gift' profitiert vom Talent 'Verbessertes Rüstung schwächen'.\n\"Lehrt Euch 'Zähes Gift'.\"" }
entries[226398] = { ["name"] = "Testament des Märtyrertums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nErfüllt den Paladin 30 Sek. lang mit heiligem Geist, wodurch alle Eure Nahkampfangriffe Eurem Ziel 50% Waffenschaden zufügen. Ihr verliert dabei jedoch Gesundheit in Höhe von 10% des verursachten Schadens. Während dieses Siegel aktiv ist, gewinnen Eure Gruppen- und Schlachtzugsmitglieder innerhalb von 40 Metern Mana in Höhe von 65% des Schadens hinzu, den Ihr durch dieses Siegel erleidet.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Gegner und verursacht sofort 85% Waffenschaden auf Kosten von Gesundheit in Höhe von 10% des verursachten Schadens.\n\nDas Siegel und das Richturteil dieser Fähigkeit profitieren von Talenten und Effekten, die das Siegel oder Richturteil von 'Siegel der Rechtschaffenheit' beeinflussen.\n\"Lehrt Euch 'Siegel des Märtyrertums'.\"" }
entries[226399] = { ["name"] = "Testament der zornigen Vergeltung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\nBenötigt Stufe 25\nErhöht 20 Sek. lang jeglichen verursachten Schaden und Heilung um 20%. Verursacht 'Vorahnung' und kann nicht eingesetzt werden, während 'Vorahnung' aktiv ist.\n\"Lehrt Euch 'Zornige Vergeltung'.\"" }
entries[226400] = { ["name"] = "Testament des Exorzisten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Paladin\n'Exorzismus' kann jetzt auf jegliche Ziele gewirkt werden und hat eine 100% höhere kritische Trefferchance gegen Untote und Dämonen.\n\"Lehrt Euch 'Exorzist'.\"" }
entries[226401] = { ["name"] = "Abhandlung über das Löwenherz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nDer Jäger beschwört das Herz eines Löwen, was alle Werte aller Verbündeten in der Nähe um 10% und deren Angriffskraft um 200 und alle Werte des Jägers um zusätzlich 10% erhöht.\n\"Lehrt Euch 'Löwenherz'.\"" }
entries[226402] = { ["name"] = "Offenbarung der schamanistischer Wut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Schamane\nReduziert sämtlichen von Euch erlittenen Schaden um 20% und Ihr regeneriert 15 Sek. lang pro Sekunde Mana in Höhe von 5% Eures maximalen Manas. Eure Gruppen- und Schlachtzugsmitglieder im Umkreis von 40 Metern erhalten zudem Mana in Höhe von 18% des von Euch auf diese Weise bezogenen Manas.\n\"Lehrt Euch 'Schamanistische Wut'.\"" }
entries[226403] = { ["name"] = "Handbuch des Fleischhakens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nWirft einen Haken mit einer Kette aus, um das Ziel zu fesseln und zu Euch zu ziehen. Kann nicht gegen Gegner eingesetzt werden, die eine höhere Stufe als ( 60 + 1) haben oder als Bossgegner markiert sind.\n\"Lehrt Euch 'Fleischhaken'.\"" }
entries[226404] = { ["name"] = "Angelaufener Real aus Undermine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (250)\n\"Diese Währung der Verlorenen Inseln wird langsam aus dem Kreislauf genommen, doch in Kalimdor und den Östlichen Königreichen erfreut sie sich nach wie vor einem überaus vorteilhaften Wechselkurs.\"" }
entries[226405] = { ["name"] = "Beschädigte Vorratskiste aus Undermine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\n\"Diese verbeulte und beschädigte Kiste sieht aus, als wäre sie buchstäblich von einem Zeppelin gefallen.\"\n<Zum Öffnen rechtsklicken>" }
entries[226406] = { ["name"] = "Rune der Schwert-Spezialisierung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger , Paladin , Jäger , Schurke , Magier , Hexenmeister\nPrägt Euren Ring mit der Rune 'Schwert-Spezialisierung':\n\nFertigkeit mit Schwertern und Zweihandschwertern um 5 erhöht. Dieser Effekt ist nicht mit Volksboni oder anderen Ringrunen stapelbar.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
