entries[226678] = { ["name"] = "Vorahnung und Voraussicht im Kampf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Umhang mit der Rune\n'Schockwelle':\n\nSchickt dem Krieger eine Druckwelle voraus, die (50 / 100 * Angriffskraft) Schaden verursacht und in einem kegelförmigen Bereich von 10 Metern alle gegnerischen Ziele 4 Sek. lang betäubt.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[226679] = { ["name"] = "Erkenntnisse des Zeitlosen Wanderers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Umhang mit der Rune 'Plötzlicher Tod':\n\nEure Nahkampftreffer haben eine Chance von 10%, Euch 'Plötzlicher Tod' zu gewähren. 'Plötzlicher Tod' ermöglicht Euch einen Einsatz von 'Hinrichten' ungeachtet der Gesundheit Eures Ziels. Wenn 'Hinrichten' durch 'Plötzlicher Tod' ermöglicht wurde, behaltet Ihr 10 Wut nach Einsatz von 'Hinrichten'.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[226680] = { ["name"] = "Rune des ersten Kriegers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Krieger\nPrägt Euren Umhang mit der Rune\n'Frischfleisch':\n\nWenn Ihr einem Ziel mit 'Blutdurst', 'Tödlicher Stoß' oder 'Schildschlag' Schaden zufügt, habt Ihr beim ersten Mal eine Chance von 100% und bei jedem weiteren Mal eine Chance von 10% in einen Wutzustand versetzt zu werden (und darauf, Fähigkeiten zu aktivieren, die einen Wutzustand erfordern). Zudem verursacht Ihr 12 Sek. lang 10% mehr körperlichen Schaden.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
entries[226694] = { ["name"] = "Rune der Verteidigungs-Spezialisierung", ["text"] = "Accountgebunden\nEinzigartig\nKlassen: Krieger , Paladin , Schurke , Schamane , Hexenmeister , Druide\nPrägt Euren Ring mit der Rune 'Verteidigungsspezialisierung':\n\nErhöht die Verteidigungsfertigkeit um 25. Nicht stapelbar mit anderen Ringrunen.\n\"Lehrt Euch eine neue Runenschnitzenfähigkeit.\"" }
